'use strict';
Object.assign(icons,{cloud:'M7 18h11a4 4 0 0 0 0-8h-1a6 6 0 0 0-11-2 5 5 0 0 0 1 10',rain:'M5 14a4 4 0 0 1 0-8 5 5 0 0 1 9-1 4 4 0 0 1 4 9M7 17l-2 4M13 17l-2 4M19 17l-2 4',moon:'M20 15A9 9 0 0 1 9 3 9 9 0 1 0 20 15z',snow:'M12 2v20M3 7l18 10M3 17L21 7M8 4l4 4 4-4M8 20l4-4 4 4',leaf:'M20 3C7 1 1 9 5 17c7 8 18-1 15-14zM5 20L17 6M10 14l-1-5M13 10h5'});
const ROOM_SCENES={auto:{name:'跟隨香港天氣',icon:'sun',detail:'按香港時間、實際天氣及月份切換。'},cycle:{name:'奇幻景色輪播',icon:'sparkle',detail:'每 90 秒欣賞另一種景色，時鐘及天氣資訊保持真實。'},sunny:{name:'晴朗午後',icon:'sun',detail:'暖暖陽光照入同一間小屋。',image:'assets/cottage.png'},rain:{name:'窗外細雨',icon:'rain',detail:'雨落喺窗外，小屋裡依然溫暖。',image:'assets/cottage-rain.png'},night:{name:'星光夜晚',icon:'moon',detail:'深藍夜空，配上溫暖燭光。',image:'assets/cottage-night.png'},autumn:{name:'金色秋日',icon:'leaf',detail:'窗外換上金黃、橙紅嘅秋色。',image:'assets/cottage-autumn.png'},snow:{name:'飄雪小屋',icon:'snow',detail:'幻想冬日場景，並非香港實際天氣。',image:'assets/cottage-snow.png'}};
function hkClockParts(date=new Date()){
 const parts=new Intl.DateTimeFormat('zh-HK',{timeZone:'Asia/Hong_Kong',year:'numeric',month:'numeric',day:'numeric',weekday:'long',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(date),get=t=>parts.find(p=>p.type===t)?.value||'';
 return {date:`${get('year')}年${get('month')}月${get('day')}日`,weekday:get('weekday'),time:`${get('hour')}:${get('minute')}`,seconds:get('second'),hour:Number(get('hour')),month:Number(get('month'))};
}
function isRainWeather(w){return w?.available&&!w.stale&&[53,54,62,63,64,65].includes(w.code)}
function automaticRoomScene(date,weather){const p=hkClockParts(date);if(p.hour>=18||p.hour<6)return 'night';if(isRainWeather(weather))return 'rain';if(p.month>=9&&p.month<=11)return 'autumn';return 'sunny'}
let roomSceneMode='auto';try{const mode=localStorage.getItem('starlight-room-scene-v1');if(ROOM_SCENES[mode])roomSceneMode=mode}catch{}
let roomWeather={available:false,loading:true},lastWeatherFetch=0,weatherRequest=null,environmentClock=null,environmentSizeObserver=null,sceneRequest=0,cycleStarted=Date.now(),activeRoomScene=null;
const sceneCycle=['sunny','rain','autumn','night','snow'];
function desiredRoomScene(now=new Date()){if(roomSceneMode==='auto')return automaticRoomScene(now,roomWeather);if(roomSceneMode==='cycle')return sceneCycle[Math.floor((now.getTime()-cycleStarted)/90000)%sceneCycle.length];return roomSceneMode}
function weatherGlyph(w){if(!w.available)return 'cloud';if(isRainWeather(w))return 'rain';if(w.code>=70&&w.code<=77)return 'moon';if([60,61,76,83,84,85].includes(w.code))return 'cloud';return 'sun'}
function weatherReadout(){if(roomWeather.loading)return '香港天氣更新中…';if(!roomWeather.available)return '天氣暫未能更新';return `${roomWeather.description} · ${roomWeather.temperature}°C`}
function roomClockMarkup(){const p=hkClockParts();return `<section class="room-clock-panel" aria-label="香港日期、時間及天氣"><div class="room-date-row"><time id="room-date">${p.date}</time><span id="room-weekday">${p.weekday}</span></div><div class="room-time-row"><div class="room-live-time"><time id="room-time" aria-label="香港時間">${p.time}</time><span id="room-seconds">${p.seconds}</span><small>香港時間 HKT</small></div><div class="room-weather-summary"><button type="button" data-room-environment="refresh" aria-label="重新取得香港天氣"><span id="room-weather-icon">${icon(weatherGlyph(roomWeather))}</span><span id="room-weather-text">${weatherReadout()}</span></button><a href="https://www.hko.gov.hk/tc/wxinfo/currwx/current.htm" target="_blank" rel="noopener noreferrer" id="room-weather-source">香港天文台${roomWeather.available?' · '+weatherTimestamp(roomWeather.updatedAt):''}${roomWeather.stale?' · 資料待更新':''}</a></div></div></section>`}
function weatherTimestamp(stamp){if(!stamp)return '';return new Intl.DateTimeFormat('zh-HK',{timeZone:'Asia/Hong_Kong',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(stamp))+' 更新'}
function outdoorEffects(){return `<svg class="weather-mask-defs" width="0" height="0" aria-hidden="true"><defs><clipPath id="cottage-window-mask" clipPathUnits="objectBoundingBox"><path d="M.166 .245L.194 .177 .237 .245 .237 .525 .166 .525Z M.282 .232L.313 .177 .377 .179 .377 .554 .282 .554Z M.495 0H.621V.127H.495Z M.911 .215L.955 .139 .989 .211 .989 .565 .911 .565Z"/></clipPath></defs></svg><div class="room-weather-outdoors" aria-hidden="true"><div class="window-rain"></div><div class="window-snow">${Array.from({length:45},(_,i)=>`<i style="left:${(i*37.7)%100}%;top:${(i*17.9)%100}%;--fall:${6+i%9}s;--delay:-${i%13}s;--flake:${2+i%4}px"></i>`).join('')}</div><div class="window-leaves">${Array.from({length:16},(_,i)=>`<i style="left:${(i*47)%100}%;top:${(i*23)%100}%;--fall:${8+i%7}s;--delay:-${i%12}s;--leaf-color:${['#c9974f','#c36b38','#a5873f','#e5ba68'][i%4]}"></i>`).join('')}</div></div>`}
const baseEnvironmentRoom=room;
room=function(){return baseEnvironmentRoom().replace(/<div class="room-welcome">[\s\S]*?<\/div><button class="hotspot/,roomClockMarkup()+`<button class="room-scene-control" data-room-environment="choose"><span>${icon('sun')}</span><span><small>窗外景色</small><strong id="room-scene-name">${ROOM_SCENES[roomSceneMode].name}</strong></span>${icon('arrow')}</button>`+outdoorEffects()+'<button class="hotspot').replace('<div class="scenery"></div>','<div class="scenery room-environment-art"><div class="room-scene-frame" data-scene-slot="0"></div><div class="room-scene-frame" data-scene-slot="1"></div></div>')};
function fitWindowEffects(){const root=$('.screen.room'),fx=$('.room-weather-outdoors');if(!root||!fx)return;const rect=root.getBoundingClientRect(),scale=Math.max(rect.width/1672,rect.height/941),w=1672*scale,h=941*scale;fx.style.width=w+'px';fx.style.height=h+'px';fx.style.left=(rect.width-w)/2+'px';fx.style.top=(rect.height-h)/2+'px'}
function updateWeatherUI(){const text=$('#room-weather-text');if(!text)return;text.textContent=weatherReadout();$('#room-weather-icon').innerHTML=icon(weatherGlyph(roomWeather));$('#room-weather-source').textContent='香港天文台'+(roomWeather.available?' · '+weatherTimestamp(roomWeather.updatedAt):'')+(roomWeather.stale?' · 資料待更新':'')}
async function fetchRoomWeather(force=false){if(weatherRequest)return weatherRequest;if(!force&&Date.now()-lastWeatherFetch<600000)return;lastWeatherFetch=Date.now();weatherRequest=(async()=>{try{const response=await fetch('/api/weather');if(!response.ok)throw new Error('weather');roomWeather=await response.json();roomWeather.loading=false}catch{roomWeather={...roomWeather,loading:false,...(roomWeather.available?{stale:true}:{available:false})}}finally{weatherRequest=null;updateWeatherUI();updateRoomScene()}})();return weatherRequest}
async function updateRoomScene(){const root=$('.screen.room');if(!root)return;const scene=desiredRoomScene(),sceneInfo=ROOM_SCENES[scene];const rain=roomSceneMode==='auto'?isRainWeather(roomWeather):scene==='rain';root.dataset.precipitation=rain?'rain':scene==='snow'?'snow':'none';root.dataset.roomScene=scene;root.dataset.scenePreview=roomSceneMode==='auto'?'false':'true';const name=$('#room-scene-name');if(name)name.textContent=roomSceneMode==='auto'?`自動 · ${sceneInfo.name}`:roomSceneMode==='cycle'?`輪播 · ${sceneInfo.name}`:scene==='snow'?'飄雪 · 幻想景色':`預覽 · ${sceneInfo.name}`;
 if(activeRoomScene===scene)return;const request=++sceneRequest;const slots=[...root.querySelectorAll('.room-scene-frame')];if(!slots.length)return;
 const image=new Image();image.src=sceneInfo.image;try{await image.decode()}catch{if(request===sceneRequest&&document.contains(root)){root.dataset.sceneImage='fallback';activeRoomScene=null}return}if(request!==sceneRequest||!document.contains(root))return;root.dataset.sceneImage='loaded';const current=slots.find(f=>f.classList.contains('active')),next=slots.find(f=>f!==current)||slots[0];next.style.backgroundImage=`url("${sceneInfo.image}")`;next.classList.add('active');current?.classList.remove('active');activeRoomScene=scene;
}
function environmentTick(){if(page!=='room'||!$('.screen.room')){clearInterval(environmentClock);environmentClock=null;environmentSizeObserver?.disconnect();environmentSizeObserver=null;return}const p=hkClockParts();$('#room-date').textContent=p.date;$('#room-weekday').textContent=p.weekday;$('#room-time').textContent=p.time;$('#room-seconds').textContent=p.seconds;updateRoomScene();if(Date.now()-lastWeatherFetch>=600000)fetchRoomWeather()}
function initializeRoomEnvironment(){clearInterval(environmentClock);environmentSizeObserver?.disconnect();activeRoomScene=null;fitWindowEffects();if(typeof ResizeObserver!=='undefined'){environmentSizeObserver=new ResizeObserver(fitWindowEffects);environmentSizeObserver.observe($('.screen.room'))}updateWeatherUI();updateRoomScene();fetchRoomWeather();environmentClock=setInterval(environmentTick,1000)}
const baseEnvironmentRender=render;
render=function(){clearInterval(environmentClock);environmentClock=null;environmentSizeObserver?.disconnect();environmentSizeObserver=null;baseEnvironmentRender();if(page==='room')initializeRoomEnvironment()};
function sceneChooser(){openModal('room-scenes',`<p class="subtle">同一間小屋，只改變窗外景色同光線。左上角嘅日期、時間及香港天氣會一直保持真實。</p><div class="room-scene-options">${Object.entries(ROOM_SCENES).map(([key,s])=>`<button class="scene-option ${key===roomSceneMode?'selected':''}" data-room-scene="${key}" aria-pressed="${key===roomSceneMode}"><span>${icon(s.icon)}</span><strong>${s.name}</strong><small>${s.detail}</small>${key===roomSceneMode?'<i>已選</i>':''}</button>`).join('')}</div>`,'窗外景色')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||sessionRole!=='child')return;if(b.dataset.roomEnvironment==='choose'){lastFocus=b;sceneChooser();return}if(b.dataset.roomEnvironment==='refresh'){fetchRoomWeather(true);notify('正在更新香港天氣。');return}if(b.dataset.roomScene&&ROOM_SCENES[b.dataset.roomScene]){roomSceneMode=b.dataset.roomScene;cycleStarted=Date.now();try{localStorage.setItem('starlight-room-scene-v1',roomSceneMode)}catch{}closeModal();updateRoomScene();notify(roomSceneMode==='auto'?'小屋景色會跟隨香港時間同天氣。':roomSceneMode==='cycle'?'已開啟奇幻輪播，真實天氣資料會保持顯示。':'已切換窗外景色。')}});
render();
